const MOD = 1000000007;
const K = 1010;

function mulmod(a, b) {
	const ah = Math.floor(a / 65536), al = a % 65536;
	return ((ah * b % MOD) * 65536 + al * b) % MOD;
}

function powmod(a, x) {
	if (x === 0) return 1;
	if (x % 2 === 0) return powmod(mulmod(a, a), x / 2);
	return mulmod(a, powmod(a, x - 1));
}

const dp = new Int32Array(K * K);

function main() {
	const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);
	const k = parseInt(data[0]), va = parseInt(data[1]), vb = parseInt(data[2]);

	const den = powmod((va + vb) % MOD, MOD - 2);
	const pa = mulmod(va % MOD, den);
	const pb = mulmod(vb % MOD, den);
	const one_b = mulmod(pa, powmod(pb, MOD - 2));

	for (let i = k - 1; i >= 0; i--) {
		for (let j = k; j >= 1; j--) {
			if (i + j >= k) {
				dp[i * K + j] = (i + j + one_b) % MOD;
			} else {
				dp[i * K + j] = (mulmod(pa, dp[i * K + j + 1]) + mulmod(pb, dp[(i + j) * K + j])) % MOD;
			}
		}
	}
	process.stdout.write(dp[0 * K + 1] + "\n");
}

main();
